/**
 * Higher-Order Spectral Analysis (HOSA): Bispectrum & Bicoherence Estimator
 *
 * Traditional Fourier Power Spectrum (|X(f)|^2) suppresses all phase information.
 * The Bispectrum B(f1, f2) = E[X(f1) * X(f2) * X*(f1 + f2)] measures third-order
 * cumulants in the frequency domain.
 *
 * Normalized Squared Bicoherence:
 *   b^2(f1, f2) = |B(f1, f2)|^2 / ( E[|X(f1)*X(f2)|^2] * E[|X(f1+f2)|^2] )
 *
 * Properties:
 * - 0 <= b^2(f1, f2) <= 1
 * - Detects Quadratic Phase Coupling (QPC) between harmonic frequencies.
 * - Background ambient power hum generated by physical transformer magnetostriction
 *   exhibits strong bicoherence peaks at (50Hz, 50Hz)->100Hz and (50Hz, 100Hz)->150Hz.
 * - Synthetic hum or gaussian noise exhibits zero phase coupling (b^2 ~ 0).
 */

import FFT from 'fft.js';

export interface BicoherenceResult {
  hasQuadraticPhaseCoupling: boolean;
  peakBicoherence: number; // 0 to 1
  peakFrequenciesHz: [number, number]; // [f1, f2]
  sumFrequencyHz: number; // f1 + f2
  isAuthenticPhysicalHum: boolean; // true if physical grid transformer, false if synthetic
  bicoherenceMatrix: number[][]; // 2D grid for visualization
  frequencyAxisHz: number[];
  analysisTimeMs: number;
}

export function computeBicoherence(
  channelData: Float32Array,
  sampleRate: number,
  options?: {
    maxFreqHz?: number;
    segmentSize?: number;
    gridResolution?: number;
  }
): BicoherenceResult {
  const t0 = performance.now();
  const maxFreq = options?.maxFreqHz ?? 250; // Focus on power grid & sub-harmonic band
  const segmentSize = options?.segmentSize ?? 512;
  const gridRes = options?.gridResolution ?? 24;

  const fft = new FFT(segmentSize);
  const halfN = segmentSize / 2;
  const freqStep = sampleRate / segmentSize;
  const maxBin = Math.min(halfN - 1, Math.floor(maxFreq / freqStep));

  // Determine grid bin indices spanning [10Hz, maxFreq]
  const minBin = Math.max(1, Math.floor(15 / freqStep));
  const binStep = Math.max(1, Math.floor((maxBin - minBin) / gridRes));
  const bins: number[] = [];
  for (let b = minBin; b <= maxBin; b += binStep) {
    bins.push(b);
  }
  const K = bins.length;

  const hop = Math.floor(segmentSize / 2);
  const numSegments = Math.min(64, Math.floor((channelData.length - segmentSize) / hop));

  if (numSegments < 4) {
    return {
      hasQuadraticPhaseCoupling: false,
      peakBicoherence: 0,
      peakFrequenciesHz: [0, 0],
      sumFrequencyHz: 0,
      isAuthenticPhysicalHum: false,
      bicoherenceMatrix: Array.from({ length: K }, () => new Array(K).fill(0)),
      frequencyAxisHz: bins.map((b) => Number((b * freqStep).toFixed(1))),
      analysisTimeMs: 0,
    };
  }

  // Pre-allocate DFT buffers
  const realInput = new Float64Array(segmentSize);
  const complexOut = fft.createComplexArray();

  // Matrices to accumulate expectations across segments
  // B_re, B_im: bispectrum accumulator
  // P_prod: denominator expectation of |X(f1) * X(f2)|^2
  // P_sum: denominator expectation of |X(f1 + f2)|^2
  const B_re: Float64Array[] = Array.from({ length: K }, () => new Float64Array(K));
  const B_im: Float64Array[] = Array.from({ length: K }, () => new Float64Array(K));
  const P_prod: Float64Array[] = Array.from({ length: K }, () => new Float64Array(K));
  const P_sum: Float64Array[] = Array.from({ length: K }, () => new Float64Array(K));

  // Hann window
  const window = new Float64Array(segmentSize);
  for (let i = 0; i < segmentSize; i++) {
    window[i] = 0.5 * (1 - Math.cos((2 * Math.PI * i) / (segmentSize - 1)));
  }

  for (let m = 0; m < numSegments; m++) {
    const offset = m * hop;
    for (let i = 0; i < segmentSize; i++) {
      realInput[i] = channelData[offset + i] * window[i];
    }

    fft.realTransform(complexOut, realInput);
    fft.completeSpectrum(complexOut);

    // Extract complex bins
    for (let i = 0; i < K; i++) {
      const b1 = bins[i];
      const re1 = complexOut[2 * b1];
      const im1 = complexOut[2 * b1 + 1];
      const mag1Sq = re1 * re1 + im1 * im1;

      for (let j = 0; j <= i; j++) {
        const b2 = bins[j];
        const b3 = b1 + b2; // sum frequency
        if (b3 >= halfN) continue;

        const re2 = complexOut[2 * b2];
        const im2 = complexOut[2 * b2 + 1];
        const mag2Sq = re2 * re2 + im2 * im2;

        const re3 = complexOut[2 * b3];
        const im3 = complexOut[2 * b3 + 1];
        const mag3Sq = re3 * re3 + im3 * im3;

        // X(f1) * X(f2)
        const reProd = re1 * re2 - im1 * im2;
        const imProd = re1 * im2 + im1 * re2;

        // X(f1) * X(f2) * X*(f1+f2) = (reProd + j*imProd) * (re3 - j*im3)
        const bRe = reProd * re3 + imProd * im3;
        const bIm = imProd * re3 - reProd * im3;

        B_re[i][j] += bRe;
        B_im[i][j] += bIm;
        P_prod[i][j] += mag1Sq * mag2Sq;
        P_sum[i][j] += mag3Sq;
      }
    }
  }

  // Compute final squared bicoherence matrix b^2(f1, f2)
  let peakBicoherence = 0;
  let peakF1 = 0;
  let peakF2 = 0;

  const bicoherenceMatrix: number[][] = Array.from({ length: K }, () => new Array(K).fill(0));
  const invM = 1.0 / numSegments;

  for (let i = 0; i < K; i++) {
    const f1 = bins[i] * freqStep;
    for (let j = 0; j <= i; j++) {
      const f2 = bins[j] * freqStep;

      const numMagSq = (B_re[i][j] * invM) ** 2 + (B_im[i][j] * invM) ** 2;
      const den = (P_prod[i][j] * invM) * (P_sum[i][j] * invM);

      let bic = 0;
      if (den > 1e-12) {
        bic = Math.min(1.0, numMagSq / den);
      }

      bicoherenceMatrix[i][j] = Number(bic.toFixed(3));
      bicoherenceMatrix[j][i] = bicoherenceMatrix[i][j]; // symmetric

      if (bic > peakBicoherence) {
        peakBicoherence = bic;
        peakF1 = f1;
        peakF2 = f2;
      }
    }
  }

  // Authentic physical grid transformers display high phase coupling (bic >= 0.45)
  // especially near 50Hz or 60Hz fundamentals and their harmonic sum frequencies
  const isNearGrid = (Math.abs(peakF1 - 50) < 6 || Math.abs(peakF1 - 60) < 6 ||
                      Math.abs(peakF2 - 50) < 6 || Math.abs(peakF2 - 60) < 6);

  const hasQPC = peakBicoherence >= 0.42;
  const isAuthentic = hasQPC && isNearGrid;

  const analysisTimeMs = Number((performance.now() - t0).toFixed(2));

  return {
    hasQuadraticPhaseCoupling: hasQPC,
    peakBicoherence: Number(peakBicoherence.toFixed(3)),
    peakFrequenciesHz: [Number(peakF1.toFixed(1)), Number(peakF2.toFixed(1))],
    sumFrequencyHz: Number((peakF1 + peakF2).toFixed(1)),
    isAuthenticPhysicalHum: isAuthentic,
    bicoherenceMatrix,
    frequencyAxisHz: bins.map((b) => Number((b * freqStep).toFixed(1))),
    analysisTimeMs,
  };
}
